package com.example.discovery.provider;import static org.assertj.core.api.Assertions.assertThat;import com.example.discovery.provider.api.PaymentController;import com.example.discovery.provider.config.ProviderProperties;import java.time.Duration;import org.junit.jupiter.api.Test;class PaymentControllerTest{@Test void returnsInstanceMetadata(){var c=new PaymentController(new ProviderProperties("payment-service","payment-service-8081","localhost",8081,"http://localhost:8761",Duration.ofSeconds(3)));var r=c.payments();assertThat(r.instanceId()).isEqualTo("payment-service-8081");assertThat(r.port()).isEqualTo(8081);}}
